 hero.querySelector('.of-lead').textContent='From product development to custom manufacturing, BOOM helps brands turn drinkware concepts into production-ready products. Start with an existing model, modify a component or develop a new plastic or silicone product.';
 const heroImg=hero.querySelector('img');heroImg.loading='eager';heroImg.fetchPriority='high';heroImg.alt='BOOM drinkware showroom with plastic and silicone product models';
 hero.querySelector('figure').appendChild(make('<figcaption>From the showroom to the production floor.<br>Plastic & silicone · Shenzhen, China</figcaption>'));
 const project=hero.querySelector('.of-button');project.href='#project-enquiry';
 const cap=make(`<section class="of-section u-capabilities" id="manufacturing-capabilities"><div class="of-wrap">${heading('01 / MANUFACTURING CAPABILITIES','Built around the product.<br>Grounded in manufacturing.','Plastic cup manufacturing and silicone processing are reviewed against your selected model, intended use and project specification. Tooling, assembly, decoration and inspection form one agreed production scope.')}<div class="u-factory-pair">${figure('/img/archive-real-20261103/081-56ed5ab019.webp','Injection molding floor at the BOOM Drinkware factory','01 / Plastic processing · existing factory photograph')}${figure('/img/archive-real-20261103/070-bf8b50e360.webp','Mold making and repair workshop at the BOOM Drinkware factory','02 / Mold development · existing factory photograph')}</div><div class="u-cap-list">${[['Mold development','Review drawings, changed components and tooling requirements before cutting a mold.'],['Plastic processing','Confirm the resin, wall sections, dimensions and component fit for the selected model.'],['Silicone processing','Agree the silicone specification, shape and color against the intended use.'],['Product assembly','Review the body, lid, straw, handle and any LED components as an assembly.'],['Decoration','Select artwork methods for the material, surface and print area.'],['Quality inspection','Agree acceptance criteria, sample approval and packing checks before production.']].map(([t,p],i)=>`<div><span>0${i+1}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><a class="u-link" href="/factory/">Review our factory and supply scope ↗</a></div></section>`);
 hero.after(cap);
 sections[1].id='development-routes';
