 sections[2].querySelector('.of-wrap').append(comparison);sections[2].id='oem-vs-odm';
 const platforms=make(`<section class="of-section u-platforms" id="product-platforms"><div class="of-wrap">${heading('PRODUCT PLATFORMS','One development brief.<br>Different starting points.','Choose a product platform first. Material, components and decoration are then reviewed for your project.')}<div class="u-platform-grid">${[['Silicone','Flexible product forms, color and shape options.','/custom-silicone-cups/','/img/real-shots-20261028/product-close/sil-01-gjb-001-1200.webp','Silicone cup product reference'],['Plastic','Existing cup bodies or a structure developed to specification.','/custom-plastic-cups/','/img/real-shots-20261028/product-bbq/hjb-073-1200.webp','Plastic drinkware product reference'],['Tritan','Review the selected resin, cup body and component combination.','/tritan-drinkware/','/img/buyer-experience/oem-development-one-part.webp','Component development illustration; not a material certification'],['LED','Review the cup, light module, activation and assembly together.','/custom-led-drinkware/','/img/real-shots-20261028/product-close/led-03-fgb-006-1200.webp','LED cup product reference']].map(([t,d,h,src,alt])=>`<a href="${h}"><img src="${src}" alt="${alt}" width="600" height="600" loading="lazy"><span>${t} <b>↗</b></span><p>${d}</p></a>`).join('')}</div><p class="of-note">Product and development reference visuals; scene composites and development illustrations are not order photographs. Tritan material and suitability must be confirmed for the selected model.</p><div class="u-intent-links"><a href="/bulk-drinkware/">Buying in quantity? Explore bulk drinkware ↗</a><a href="/private-label-drinkware/">Looking for an existing branded range? Private label drinkware ↗</a></div></div></section>`);
 sections[2].after(platforms);
